1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { useParams, useRouter } from "next/navigation";
5	import {
6	  ArrowLeft,
7	  Bell,
8	  Calendar,
9	  CheckCircle2,
10	  ExternalLink,
11	  FileText,
12	  Loader2,
13	  MapPin,
14	  MessageSquare,
15	  Music,
16	  Package,
17	  Phone,
18	  Plus,
19	  Save,
20	  Send,
21	  ShieldCheck,
22	  Tag,
23	  Trash2,
24	  User,
25	  Video,
26	  X,
27	} from "lucide-react";
28	import { cn } from "@/lib/utils";
29	
30	// ── Types ──────────────────────────────────────────────────────────────────
31	
32	interface JvtoCustomer {
33	  id: number;
34	  name: string;
35	  phone: string;
36	  email: string;
37	  category: "JVTO" | "KLOOK";
38	  package: {
39	    id: number | null;
40	    code: string;
41	    name: string;
42	    link: string;
43	    duration: { day: number | string; night: number | string };
44	  };
45	  booking: {
46	    id: number;
47	    code: string;
48	    numb_of_pax: number;
49	    travel_date_start: string;
50	    travel_date_end: string;
51	    booking_date: string;
52	    pickup: { location: string; time: string };
53	    drop: { location: string; time: string };
54	  };
55	}
56	
57	interface ChatMessage {
58	  id: string;
59	  direction: "IN" | "OUT";
60	  content: string | null;
61	  mediaType: string | null;
62	  mediaData: Record<string, unknown> | null;
63	  createdAt: string;
64	  number: { id: string; label: string; phoneNumber: string | null };
65	}
66	
67	interface CrmData {
68	  id: string;
69	  notes: string | null;
70	  pipelineStageId: string | null;
71	  pipelineStage: { id: string; name: string; color: string } | null;
72	  labels: Array<{ id: string; name: string; color: string }>;
73	  adminNotes: Array<{ id: string; content: string; createdAt: string }>;
74	  reminders: Array<{ id: string; description: string; dueDate: string; isCompleted: boolean }>;
75	}
76	
77	interface WaNumber {
78	  id: string;
79	  label: string;
80	  phoneNumber: string | null;
81	}
82	
83	// ── Helpers ────────────────────────────────────────────────────────────────
84	
85	const FormattedDate = ({ date }: { date: string }) => {
86	  const [m, setM] = useState(false);
87	  useEffect(() => setM(true), []);
88	  return m ? <span>{new Date(date).toLocaleDateString()}</span> : <span>…</span>;
89	};
90	
91	const FormattedTime = ({ date }: { date: string }) => {
92	  const [m, setM] = useState(false);
93	  useEffect(() => setM(true), []);
94	  return m ? (
95	    <span>{new Date(date).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span>
96	  ) : (
97	    <span>…</span>
98	  );
99	};
100	
101	function fmt(date: string) {
102	  return new Date(date).toLocaleDateString("en-US", {
103	    month: "short",
104	    day: "numeric",
105	    year: "numeric",
106	  });
107	}
108	
109	// ── Media Preview ─────────────────────────────────────────────────────────
110	
111	function MediaPreview({ msg, isOut }: { msg: ChatMessage; isOut: boolean }) {
112	  const { mediaType, mediaData, id } = msg;
113	  if (!mediaType) return null;
114	
115	  const localFile = mediaData?.localFile as string | undefined;
116	  const mimetype = mediaData?.mimetype as string | undefined;
117	  const mediaUrl = localFile ? `/api/media/${id}` : null;
118	
119	  const dimClass = "rounded-lg overflow-hidden max-w-[220px]";
120	  const placeholderClass = cn(
121	    "flex items-center gap-2 rounded-lg border px-3 py-2 text-xs",
122	    isOut ? "border-white/30 text-white/80" : "border-slate-200 text-slate-500"
123	  );
124	
125	  if (mediaType === "imageMessage" || mediaType === "stickerMessage") {
126	    if (mediaUrl) {
127	      return (
128	        <a href={mediaUrl} target="_blank" rel="noopener noreferrer" className={dimClass}>
129	          {/* eslint-disable-next-line @next/next/no-img-element */}
130	          <img src={mediaUrl} alt="image" className="max-h-48 w-full object-cover" />
131	        </a>
132	      );
133	    }
134	    return <span className={placeholderClass}>[Image — not available]</span>;
135	  }
136	
137	  if (mediaType === "videoMessage") {
138	    if (mediaUrl) {
139	      return (
140	        <div className={dimClass}>
141	          <video src={mediaUrl} controls className="max-h-48 w-full" />
142	        </div>
143	      );
144	    }
145	    return (
146	      <span className={placeholderClass}>
147	        <Video className="h-3.5 w-3.5 shrink-0" /> Video — not available
148	      </span>
149	    );
150	  }
151	
152	  if (mediaType === "audioMessage") {
153	    if (mediaUrl) {
154	      return <audio src={mediaUrl} controls className="max-w-[220px]" />;
155	    }
156	    return (
157	      <span className={placeholderClass}>
158	        <Music className="h-3.5 w-3.5 shrink-0" /> Audio — not available
159	      </span>
160	    );
161	  }
162	
163	  if (mediaType === "documentMessage") {
164	    const filename = (mediaData?.filename as string) ?? (mimetype ?? "document");
165	    if (mediaUrl) {
166	      return (
167	        <a href={mediaUrl} target="_blank" rel="noopener noreferrer" className={placeholderClass + " hover:opacity-80"}>
168	          <FileText className="h-3.5 w-3.5 shrink-0" />
169	          <span className="truncate max-w-[160px]">{filename}</span>
170	          <ExternalLink className="h-3 w-3 shrink-0 opacity-60" />
171	        </a>
172	      );
173	    }
174	    return (
175	      <span className={placeholderClass}>
176	        <FileText className="h-3.5 w-3.5 shrink-0" /> {filename}
177	      </span>
178	    );
179	  }
180	
181	  if (mediaType === "locationMessage" || mediaType === "liveLocationMessage") {
182	    const lat = mediaData?.latitude;
183	    const lng = mediaData?.longitude;
184	    const name = mediaData?.name as string | undefined;
185	    if (lat && lng) {
186	      return (
187	        <a
188	          href={`https://maps.google.com/?q=${lat},${lng}`}
189	          target="_blank"
190	          rel="noopener noreferrer"
191	          className={placeholderClass + " hover:opacity-80"}
192	        >
193	          <MapPin className="h-3.5 w-3.5 shrink-0" />
194	          {name ?? `${lat}, ${lng}`}
195	        </a>
196	      );
197	    }
198	    return <span className={placeholderClass}><MapPin className="h-3.5 w-3.5 shrink-0" /> Location</span>;
199	  }
200	
201	  if (mediaType === "contactMessage" || mediaType === "contactsArrayMessage") {
202	    const displayName = mediaData?.displayName as string | undefined;
203	    return <span className={placeholderClass}><User className="h-3.5 w-3.5 shrink-0" /> Contact{displayName ? `: ${displayName}` : ""}</span>;
204	  }
205	
206	  return <span className={placeholderClass}>[{mediaType}]</span>;
207	}
208	
209	// ── Component ──────────────────────────────────────────────────────────────
210	
211	export default function CustomerDetailClient() {
212	  const { id } = useParams<{ id: string }>();
213	  const router = useRouter();
214	
215	  const [customer, setCustomer] = useState<JvtoCustomer | null>(null);
216	  const [crm, setCrm] = useState<CrmData | null>(null);
217	  const [messages, setMessages] = useState<ChatMessage[]>([]);
218	  const [waNumbers, setWaNumbers] = useState<WaNumber[]>([]);
219	  const [stages, setStages] = useState<Array<{ id: string; name: string; color: string }>>([]);
220	  const [allLabels, setAllLabels] = useState<Array<{ id: string; name: string; color: string }>>([]);
221	
222	  const [loading, setLoading] = useState(true);
223	  const [activeTab, setActiveTab] = useState<"chat" | "crm">("chat");
224	
225	  // Send message
226	  const [selectedNumber, setSelectedNumber] = useState("");
227	  const [msgText, setMsgText] = useState("");
228	  const [sending, setSending] = useState(false);
229	  const chatEndRef = useRef<HTMLDivElement>(null);
230	
231	  // CRM state
232	  const [newNote, setNewNote] = useState("");
233	  const [addingNote, setAddingNote] = useState(false);
234	  const [reminderDesc, setReminderDesc] = useState("");
235	  const [reminderDate, setReminderDate] = useState("");
236	  const [addingReminder, setAddingReminder] = useState(false);
237	  const [showLabelPicker, setShowLabelPicker] = useState(false);
238	  const [editingNotes, setEditingNotes] = useState(false);
239	  const [notesText, setNotesText] = useState("");
240	  const [savingNotes, setSavingNotes] = useState(false);
241	
242	  // ── Fetch ────────────────────────────────────────────────────────────────
243	
244	  const fetchAll = async () => {
245	    try {
246	      const [custRes, crmRes, numRes, pipeRes, labRes] = await Promise.all([
247	        fetch(`/api/jvto/customers/${id}`),
248	        fetch(`/api/jvto/crm/${id}`),
249	        fetch("/api/numbers"),
250	        fetch("/api/pipeline?slim=true"),
251	        fetch("/api/labels"),
252	      ]);
253	
254	      if (!custRes.ok) { router.push("/customers"); return; }
255	
256	      const custData = await custRes.json();
257	      const crmData = crmRes.ok ? await crmRes.json() : null;
258	      const numData = numRes.ok ? await numRes.json() : [];
259	      const pipeData = pipeRes.ok ? await pipeRes.json() : [];
260	      const labData = labRes.ok ? await labRes.json() : [];
261	
262	      setCustomer(custData.data);
263	      setCrm(crmData);
264	      setWaNumbers(Array.isArray(numData) ? numData : []);
265	      setStages(Array.isArray(pipeData) ? pipeData : []);
266	      setAllLabels(Array.isArray(labData) ? labData : []);
267	      if (Array.isArray(numData) && numData.length > 0) {
268	        setSelectedNumber((prev) => prev || numData[0].id);
269	      }
270	    } catch (err) {
271	      console.error(err);
272	    } finally {
273	      setLoading(false);
274	    }
275	  };
276	
277	  const fetchMessages = async () => {
278	    if (!customer) return;
279	    try {
280	      const phone = customer.phone.replace(/\D/g, "");
281	      const res = await fetch(`/api/jvto/chat?phone=${encodeURIComponent(phone)}`);
282	      if (res.ok) {
283	        const data = await res.json();
284	        setMessages(data.messages ?? []);
285	      }
286	    } catch (err) {
287	      console.error(err);
288	    }
289	  };
290	
291	  const fetchCrm = async () => {
292	    const res = await fetch(`/api/jvto/crm/${id}`);
293	    if (res.ok) setCrm(await res.json());
294	  };
295	
296	  useEffect(() => { fetchAll(); }, [id]);
297	  useEffect(() => { if (customer) fetchMessages(); }, [customer]);
298	  useEffect(() => {
299	    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
300	  }, [messages]);
301	
302	  // ── Actions ──────────────────────────────────────────────────────────────
303	
304	  const handleSend = async (e: React.FormEvent) => {
305	    e.preventDefault();
306	    if (!msgText.trim() || !selectedNumber || !customer) return;
307	    setSending(true);
308	    try {
309	      const res = await fetch("/api/jvto/send", {
310	        method: "POST",
311	        headers: { "Content-Type": "application/json" },
312	        body: JSON.stringify({
313	          numberId: selectedNumber,
314	          phone: customer.phone,
315	          message: msgText.trim(),
316	        }),
317	      });
318	      if (res.ok) {
319	        setMsgText("");
320	        setTimeout(fetchMessages, 500);
321	      }
322	    } catch (err) { console.error(err); }
323	    finally { setSending(false); }
324	  };
325	
326	  const handleAddNote = async (e: React.FormEvent) => {
327	    e.preventDefault();
328	    if (!newNote.trim()) return;
329	    setAddingNote(true);
330	    try {
331	      const res = await fetch(`/api/jvto/crm/${id}/notes`, {
332	        method: "POST",
333	        headers: { "Content-Type": "application/json" },
334	        body: JSON.stringify({ content: newNote }),
335	      });
336	      if (res.ok) { setNewNote(""); fetchCrm(); }
337	    } catch (err) { console.error(err); }
338	    finally { setAddingNote(false); }
339	  };
340	
341	  const handleDeleteNote = async (noteId: string) => {
342	    await fetch(`/api/jvto/crm/${id}/notes?noteId=${noteId}`, { method: "DELETE" });
343	    fetchCrm();
344	  };
345	
346	  const handleAddReminder = async (e: React.FormEvent) => {
347	    e.preventDefault();
348	    if (!reminderDesc.trim() || !reminderDate) return;
349	    setAddingReminder(true);
350	    try {
351	      const res = await fetch(`/api/jvto/crm/${id}/reminders`, {
352	        method: "POST",
353	        headers: { "Content-Type": "application/json" },
354	        body: JSON.stringify({ description: reminderDesc, dueDate: reminderDate }),
355	      });
356	      if (res.ok) { setReminderDesc(""); setReminderDate(""); fetchCrm(); }
357	    } catch (err) { console.error(err); }
358	    finally { setAddingReminder(false); }
359	  };
360	
361	  const toggleReminder = async (reminderId: string, isCompleted: boolean) => {
362	    await fetch(`/api/jvto/crm/${id}/reminders`, {
363	      method: "PATCH",
364	      headers: { "Content-Type": "application/json" },
365	      body: JSON.stringify({ reminderId, isCompleted }),
366	    });
367	    fetchCrm();
368	  };
369	
370	  const deleteReminder = async (reminderId: string) => {
371	    await fetch(`/api/jvto/crm/${id}/reminders?reminderId=${reminderId}`, { method: "DELETE" });
372	    fetchCrm();
373	  };
374	
375	  const toggleLabel = async (labelId: string) => {
376	    if (!crm) return;
377	    const currentIds = crm.labels.map((l) => l.id);
378	    const newIds = currentIds.includes(labelId)
379	      ? currentIds.filter((x) => x !== labelId)
380	      : [...currentIds, labelId];
381	    await fetch(`/api/jvto/crm/${id}`, {
382	      method: "PATCH",
383	      headers: { "Content-Type": "application/json" },
384	      body: JSON.stringify({ labelIds: newIds }),
385	    });
386	    fetchCrm();
387	  };
388	
389	  const updateStage = async (stageId: string) => {
390	    await fetch(`/api/jvto/crm/${id}`, {
391	      method: "PATCH",
392	      headers: { "Content-Type": "application/json" },
393	      body: JSON.stringify({ pipelineStageId: stageId }),
394	    });
395	    fetchCrm();
396	  };
397	
398	  const saveNotes = async (e: React.FormEvent) => {
399	    e.preventDefault();
400	    setSavingNotes(true);
401	    try {
402	      await fetch(`/api/jvto/crm/${id}`, {
403	        method: "PATCH",
404	        headers: { "Content-Type": "application/json" },
405	        body: JSON.stringify({ notes: notesText.trim() || null }),
406	      });
407	      setEditingNotes(false);
408	      fetchCrm();
409	    } catch (err) { console.error(err); }
410	    finally { setSavingNotes(false); }
411	  };
412	
413	  // ── Render ────────────────────────────────────────────────────────────────
414	
415	  if (loading) {
416	    return (
417	      <div className="flex flex-col items-center justify-center py-40 text-slate-400">
418	        <Loader2 className="mb-4 h-10 w-10 animate-spin text-[#546dfe]" />
419	        <p className="text-xs font-semibold uppercase tracking-[0.18em]">Loading customer...</p>
420	      </div>
421	    );
422	  }
423	
424	  if (!customer) return null;
425	
426	  const phone = customer.phone.replace(/^\+/, "");
427	
428	  return (
429	    <div className="space-y-5 pb-12">
430	      {/* Header */}
431	      <div className="flex items-center gap-3">
432	        <button onClick={() => router.push("/customers")} className="app-icon-button h-9 w-9">
433	          <ArrowLeft className="h-4 w-4" />
434	        </button>
435	        <div>
436	          <p className="text-xs font-semibold uppercase tracking-[0.16em] text-slate-400">
437	            Customer Profile · {customer.category}
438	          </p>
439	          <h1 className="mt-0.5 text-2xl font-semibold tracking-[-0.03em] text-slate-900">
440	            {customer.name}
441	          </h1>
442	        </div>
443	      </div>
444	
445	      {/* Info card */}
446	      <div className="app-card p-6">
447	        <div className="flex flex-col gap-5 lg:flex-row lg:items-start lg:justify-between">
448	          <div className="flex items-start gap-4">
449	            <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-xl bg-[#eef1ff] text-xl font-bold text-[#546dfe]">
450	              {customer.name[0] ?? <User className="h-6 w-6" />}
451	            </div>
452	            <div>
453	              <div className="flex flex-wrap items-center gap-2">
454	                <h2 className="text-xl font-semibold text-slate-900">{customer.name}</h2>
455	                <span className="rounded-md bg-[#eef1ff] px-2 py-0.5 text-xs font-semibold text-[#546dfe]">
456	                  {customer.category}
457	                </span>
458	                {crm?.labels.map((l) => (
459	                  <span key={l.id} className="rounded-md px-2 py-0.5 text-xs font-semibold text-white" style={{ backgroundColor: l.color }}>
460	                    {l.name}
461	                  </span>
462	                ))}
463	              </div>
464	              <div className="mt-2 flex flex-wrap gap-x-5 gap-y-1 text-sm text-slate-500">
465	                <div className="flex items-center gap-1.5"><Phone className="h-3.5 w-3.5 text-slate-400" />{customer.phone}</div>
466	                {customer.email !== "-" && <div>{customer.email}</div>}
467	              </div>
468	            </div>
469	          </div>
470	
471	          {/* Booking summary */}
472	          <div className="rounded-xl border border-[#e6eaf4] bg-[#fafbfe] p-4 lg:min-w-[280px]">
473	            <div className="mb-3 flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.12em] text-slate-500">
474	              <Package className="h-3.5 w-3.5" /> Booking
475	            </div>
476	            <p className="font-semibold text-slate-800">{customer.package.name}</p>
477	            <p className="mt-0.5 text-xs text-slate-400">
478	              {customer.package.code !== "-" ? customer.package.code + " · " : ""}
479	              {customer.package.duration.day}D{customer.package.duration.night}N
480	              {customer.package.link !== "-" && (
481	                <a href={customer.package.link} target="_blank" rel="noopener noreferrer" className="ml-1.5 inline-flex items-center gap-0.5 text-[#546dfe] hover:underline">
482	                  <ExternalLink className="h-3 w-3" /> View
483	                </a>
484	              )}
485	            </p>
486	            <div className="mt-3 grid grid-cols-2 gap-2 text-xs text-slate-600">
487	              <div>
488	                <p className="text-slate-400">Booking code</p>
489	                <p className="font-medium">{customer.booking.code}</p>
490	              </div>
491	              <div>
492	                <p className="text-slate-400">Pax</p>
493	                <p className="font-medium">{customer.booking.numb_of_pax} pax</p>
494	              </div>
495	              <div>
496	                <p className="text-slate-400">Travel dates</p>
497	                <p className="font-medium">{fmt(customer.booking.travel_date_start)} – {fmt(customer.booking.travel_date_end)}</p>
498	              </div>
499	              {customer.booking.pickup.location !== "-" && (
500	                <div>
501	                  <p className="text-slate-400">Pickup</p>
502	                  <p className="font-medium flex items-start gap-1">
503	                    <MapPin className="mt-0.5 h-3 w-3 shrink-0 text-slate-400" />
504	                    {customer.booking.pickup.location}
505	                    {customer.booking.pickup.time !== "-" && ` · ${customer.booking.pickup.time}`}
506	                  </p>
507	                </div>
508	              )}
509	            </div>
510	          </div>
511	        </div>
512	      </div>
513	
514	      {/* Tabs */}
515	      <div className="flex items-center gap-1 border-b border-[#d8deef]">
516	        {([
517	          { key: "chat", label: "Chat History", icon: MessageSquare },
518	          { key: "crm", label: "CRM", icon: ShieldCheck },
519	        ] as const).map(({ key, label, icon: Icon }) => (
520	          <button
521	            key={key}
522	            onClick={() => setActiveTab(key)}
523	            className={cn(
524	              "relative flex items-center gap-2 px-5 py-3 text-sm font-semibold transition",
525	              activeTab === key
526	                ? "text-[#546dfe] after:absolute after:bottom-0 after:left-0 after:right-0 after:h-0.5 after:bg-[#546dfe]"
527	                : "text-slate-500 hover:text-slate-800",
528	            )}
529	          >
530	            <Icon className="h-4 w-4" />
531	            {label}
532	          </button>
533	        ))}
534	      </div>
535	
536	      {/* ── CHAT TAB ── */}
537	      {activeTab === "chat" && (
538	        <div className="grid gap-5 xl:grid-cols-[1fr_320px]">
539	          {/* Chat window */}
540	          <div className="app-card flex flex-col overflow-hidden" style={{ minHeight: "520px" }}>
541	            <div className="flex-1 overflow-y-auto p-5 space-y-3">
542	              {messages.length === 0 ? (
543	                <div className="flex h-full flex-col items-center justify-center gap-3 text-center text-slate-400 py-20">
544	                  <MessageSquare className="h-10 w-10 text-slate-200" />
545	                  <p className="text-sm font-medium">No messages yet.</p>
546	                  <p className="text-xs">Messages with {customer.phone} will appear here.</p>
547	                </div>
548	              ) : (
549	                messages.map((msg) => {
550	                  const isOut = msg.direction === "OUT";
551	                  return (
552	                    <div key={msg.id} className={cn("flex", isOut ? "justify-end" : "justify-start")}>
553	                      <div className={cn("max-w-[75%] rounded-2xl px-4 py-2.5 text-sm", isOut ? "rounded-br-sm bg-[#546dfe] text-white" : "rounded-bl-sm bg-[#f0f2f8] text-slate-800")}>
554	                        {msg.mediaType && <MediaPreview msg={msg} isOut={isOut} />}
555	                        {msg.content && <p className="mt-1 leading-[1.55]">{msg.content}</p>}
556	                        <p className={cn("mt-1 text-right text-[11px]", isOut ? "text-white/60" : "text-slate-400")}>
557	                          <FormattedTime date={msg.createdAt} />
558	                          {" · "}
559	                          <span className="font-medium">{isOut ? msg.number.label : customer.phone}</span>
560	                        </p>
561	                      </div>
562	                    </div>
563	                  );
564	                })
565	              )}
566	              <div ref={chatEndRef} />
567	            </div>
568	
569	            {/* Send form */}
570	            <div className="border-t border-[#e6eaf4] bg-[#fafbfe] p-4">
571	              <form onSubmit={handleSend} className="flex flex-col gap-3">
572	                <div className="flex items-center gap-2">
573	                  <select
574	                    value={selectedNumber}
575	                    onChange={(e) => setSelectedNumber(e.target.value)}
576	                    className="app-select flex-1 text-sm"
577	                  >
578	                    {waNumbers.map((n) => (
579	                      <option key={n.id} value={n.id}>
580	                        {n.label}{n.phoneNumber ? ` (${n.phoneNumber})` : ""}
581	                      </option>
582	                    ))}
583	                  </select>
584	                </div>
585	                <div className="flex gap-2">
586	                  <input
587	                    value={msgText}
588	                    onChange={(e) => setMsgText(e.target.value)}
589	                    placeholder={`Message to ${customer.phone}...`}
590	                    className="app-input flex-1"
591	                  />
592	                  <button
593	                    type="submit"
594	                    disabled={sending || !msgText.trim() || !selectedNumber}
595	                    className="app-button-primary px-4"
596	                  >
597	                    {sending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
598	                  </button>
599	                </div>
600	              </form>
601	            </div>
602	          </div>
603	
604	          {/* Side: pipeline */}
605	          <div className="app-card p-5">
606	            <p className="mb-3 text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">Pipeline Stage</p>
607	            <select
608	              value={crm?.pipelineStageId ?? ""}
609	              onChange={(e) => updateStage(e.target.value)}
610	              className="app-select w-full"
611	            >
612	              <option value="">Not assigned</option>
613	              {stages.map((s) => (
614	                <option key={s.id} value={s.id}>{s.name}</option>
615	              ))}
616	            </select>
617	            {crm?.pipelineStage && (
618	              <div className="mt-3 flex items-center gap-2">
619	                <span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: crm.pipelineStage.color }} />
620	                <span className="text-sm font-medium text-slate-700">{crm.pipelineStage.name}</span>
621	              </div>
622	            )}
623	          </div>
624	        </div>
625	      )}
626	
627	      {/* ── CRM TAB ── */}
628	      {activeTab === "crm" && (
629	        <div className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]">
630	          <section className="space-y-5">
631	            {/* Notes */}
632	            <div className="app-card p-6">
633	              <div className="mb-4 flex items-center gap-2">
634	                <MessageSquare className="h-5 w-5 text-[#546dfe]" />
635	                <h3 className="text-lg font-semibold text-slate-900">Interaction Notes</h3>
636	              </div>
637	              <form onSubmit={handleAddNote} className="mb-5 space-y-3">
638	                <textarea
639	                  value={newNote}
640	                  onChange={(e) => setNewNote(e.target.value)}
641	                  placeholder="Write a note about the latest interaction..."
642	                  className="app-textarea min-h-24"
643	                  rows={3}
644	                />
645	                <div className="flex justify-end">
646	                  <button type="submit" disabled={addingNote || !newNote.trim()} className="app-button-primary">
647	                    {addingNote ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
648	                    Save Note
649	                  </button>
650	                </div>
651	              </form>
652	              <div className="space-y-3">
653	                {crm?.adminNotes.length ? (
654	                  crm.adminNotes.map((note) => (
655	                    <div key={note.id} className="group relative rounded-lg border border-[#e6eaf4] bg-[#fafbfe] p-4">
656	                      <p className="text-sm leading-6 text-slate-700">{note.content}</p>
657	                      <div className="mt-2 flex items-center justify-between">
658	                        <p className="text-xs text-slate-400"><FormattedDate date={note.createdAt} /></p>
659	                        <button onClick={() => handleDeleteNote(note.id)} className="invisible text-slate-400 transition hover:text-red-500 group-hover:visible">
660	                          <Trash2 className="h-3.5 w-3.5" />
661	                        </button>
662	                      </div>
663	                    </div>
664	                  ))
665	                ) : (
666	                  <div className="rounded-lg border border-dashed border-[#d8deef] bg-[#fafbfe] px-4 py-10 text-center text-sm text-slate-400">
667	                    No interaction notes yet.
668	                  </div>
669	                )}
670	              </div>
671	            </div>
672	          </section>
673	
674	          <aside className="space-y-5">
675	            {/* Pipeline */}
676	            <div className="app-card p-5">
677	              <p className="mb-2 text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">Pipeline Stage</p>
678	              <select value={crm?.pipelineStageId ?? ""} onChange={(e) => updateStage(e.target.value)} className="app-select w-full">
679	                <option value="">Not assigned</option>
680	                {stages.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
681	              </select>
682	            </div>
683	
684	            {/* Labels */}
685	            <div className="app-card p-5">
686	              <div className="mb-3 flex items-center justify-between">
687	                <div className="flex items-center gap-2">
688	                  <ShieldCheck className="h-4 w-4 text-[#546dfe]" />
689	                  <h3 className="text-base font-semibold text-slate-900">Labels</h3>
690	                </div>
691	                <button onClick={() => setShowLabelPicker((p) => !p)} className="text-xs font-medium text-[#546dfe]">
692	                  {showLabelPicker ? "Close" : "Manage"}
693	                </button>
694	              </div>
695	              <div className="flex flex-wrap gap-1.5">
696	                {crm?.labels.length ? (
697	                  crm.labels.map((l) => (
698	                    <span key={l.id} className="rounded-md px-2 py-1 text-xs font-semibold text-white" style={{ backgroundColor: l.color }}>{l.name}</span>
699	                  ))
700	                ) : (
701	                  <p className="text-xs text-slate-400">No labels.</p>
702	                )}
703	              </div>
704	              {showLabelPicker && (
705	                <div className="mt-3 space-y-1 rounded-lg border border-[#e6eaf4] bg-[#fafbfe] p-2">
706	                  {allLabels.map((label) => {
707	                    const active = crm?.labels.some((l) => l.id === label.id);
708	                    return (
709	                      <button key={label.id} onClick={() => toggleLabel(label.id)} className={cn("flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-sm transition", active ? "bg-white text-slate-900 shadow-sm" : "text-slate-600 hover:bg-white")}>
710	                        <span className="h-2 w-2 rounded-full" style={{ backgroundColor: label.color }} />
711	                        {label.name}
712	                      </button>
713	                    );
714	                  })}
715	                </div>
716	              )}
717	            </div>
718	
719	            {/* Reminders */}
720	            <div className="app-card p-5">
721	              <div className="mb-3 flex items-center gap-2">
722	                <Bell className="h-4 w-4 text-[#546dfe]" />
723	                <h3 className="text-base font-semibold text-slate-900">Reminders</h3>
724	              </div>
725	              <form onSubmit={handleAddReminder} className="mb-4 space-y-2">
726	                <input value={reminderDesc} onChange={(e) => setReminderDesc(e.target.value)} placeholder="Follow up for..." className="app-input" />
727	                <div className="flex gap-2">
728	                  <input type="date" value={reminderDate} onChange={(e) => setReminderDate(e.target.value)} className="app-input" />
729	                  <button type="submit" disabled={addingReminder} className="app-button-primary px-3">
730	                    {addingReminder ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
731	                  </button>
732	                </div>
733	              </form>
734	              <div className="space-y-2">
735	                {crm?.reminders.length ? (
736	                  crm.reminders.map((r) => (
737	                    <div key={r.id} className={cn("group flex items-start gap-2 rounded-lg border px-3 py-2.5", r.isCompleted ? "border-[#e6eaf4] bg-[#f8fafc] opacity-60" : "border-[#d8deef] bg-white")}>
738	                      <button onClick={() => toggleReminder(r.id, !r.isCompleted)} className="mt-0.5 shrink-0">
739	                        {r.isCompleted ? <CheckCircle2 className="h-4 w-4 text-[#546dfe]" /> : <Calendar className="h-4 w-4 text-slate-400" />}
740	                      </button>
741	                      <div className="min-w-0 flex-1">
742	                        <p className={cn("text-sm text-slate-800", r.isCompleted && "line-through")}>{r.description}</p>
743	                        <p className="mt-0.5 text-xs text-slate-400"><FormattedDate date={r.dueDate} /></p>
744	                      </div>
745	                      <button onClick={() => deleteReminder(r.id)} className="invisible shrink-0 text-slate-400 hover:text-red-500 group-hover:visible">
746	                        <X className="h-3.5 w-3.5" />
747	                      </button>
748	                    </div>
749	                  ))
750	                ) : (
751	                  <p className="text-xs text-slate-400">No reminders yet.</p>
752	                )}
753	              </div>
754	            </div>
755	
756	            {/* Context notes */}
757	            <div className="app-card p-5">
758	              <div className="mb-3 flex items-center justify-between">
759	                <div className="flex items-center gap-2">
760	                  <Tag className="h-4 w-4 text-[#546dfe]" />
761	                  <h3 className="text-base font-semibold text-slate-900">Context</h3>
762	                </div>
763	                {!editingNotes && (
764	                  <button onClick={() => { setNotesText(crm?.notes ?? ""); setEditingNotes(true); }} className="text-xs font-medium text-[#546dfe]">Edit</button>
765	                )}
766	              </div>
767	              {editingNotes ? (
768	                <form onSubmit={saveNotes} className="space-y-2">
769	                  <textarea value={notesText} onChange={(e) => setNotesText(e.target.value)} placeholder="Context about this customer..." className="app-textarea min-h-24" rows={3} />
770	                  <div className="flex justify-end gap-2">
771	                    <button type="button" onClick={() => setEditingNotes(false)} className="app-button-secondary">Cancel</button>
772	                    <button type="submit" disabled={savingNotes} className="app-button-primary">
773	                      {savingNotes ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
774	                      Save
775	                    </button>
776	                  </div>
777	                </form>
778	              ) : (
779	                <p className="text-sm leading-6 text-slate-600">
780	                  {crm?.notes || <span className="italic text-slate-400">No context saved.</span>}
781	                </p>
782	              )}
783	            </div>
784	          </aside>
785	        </div>
786	      )}
787	    </div>
788	  );
789	}
