        no_invented_prices: true,
        no_invented_policies: true,
        all_tours_private: true,
        redirect_booking_to_website: true,
        utm_tracking_on_links: true,
      },
      language_detection_keywords: {
        indonesian: [
          "halo", "saya", "mau", "kami", "boleh", "tolong", "mohon",
