cd "D:/wa-dashboard" && node -e "
// Test jvto-request-extractor + jvto-context-matcher (Node-compatible imports via require)
// Note: these are ESM, so we test the logic inline

const ID_KEYWORDS = ['halo','saya','mau','kami','boleh','tolong','mohon','terima kasih','berapa','untuk','dari','dengan','atau','apakah','bagaimana','paket','harga','tanggal','orang','hari','malam','perjalanan','ingin','bisa','sudah','belum','nanti'];

function detectLang(msg) {
  const d = msg.toLowerCase();
  const idCount = ID_KEYWORDS.filter(kw => d.includes(kw)).length;
  return idCount >= 3 ? 'id' : 'en';
}

const tests = [
  { msg: 'mau ke Bromo Ijen 3 hari dari Surabaya 2 orang', expected: 'id' },
  { msg: 'Hi we want Bromo and Ijen 3 days from Surabaya for 2 people', expected: 'en' },
  { msg: 'Apakah ada diskon untuk grup besar?', expected: 'id' },
];

tests.forEach(t => {
  const lang = detectLang(t.msg);
  const ok = lang === t.expected;
  console.log(ok ? '✓' : '✗', 'lang detection:', t.expected, '->', lang, '|', t.msg.slice(0, 50));
});

// Test risk signal detection
const RISK_MAP = [['diskon','discount'],['refund','refund'],['jemput saja','transport-only'],['guaranteed blue fire','weather-guarantee']];
function detectRisk(msg) {
  const d = msg.toLowerCase();
  const signals = [];
  for (const [kw, risk] of RISK_MAP) {
    if (d.includes(kw) && !signals.includes(risk)) signals.push(risk);
  }
  return signals;
}

const riskTests = [
